// "How it works": the paper's method figure, brought to life. static/live/method_live.svg is the figure itself, regenerated by
// tools/build_method_live.py with every element grouped, plus the live extras (the new part beside the build, parent-index
// labels, the (part type, parent type) flow into the oracle, token flights into the (c) tree, per-token charts).
// Performance: the camera is a CSS transform on a wrapper (.cam), composited by the browser, instead of animating the SVG
// viewBox (which repainted the whole figure every frame). The veils are separate layers that cross-fade, and the bobbing
// arch is an HTML overlay. Only reveals inside the figure repaint it.
// Flags are cumulative: step i turns on FLAGS[0..i]. CSS rules (.live.f-<flag>) decide what is shown.
(async () => {
  const W = document.getElementById('walk'), vp = document.getElementById('vp'); if (!W || !vp) return;
  const $ = (s, r = W) => r.querySelector(s), $$ = (s, r = W) => [...r.querySelectorAll(s)];
  const FW = 1100, FH = 531, NS = 'http://www.w3.org/2000/svg';
  const T0 = 148, VH = FH - T0;   // the viewport starts below the figure's format band (BrickNet / ICLF rows + legend): it shows FW x VH figure units
  const cam = document.createElement('div'); cam.className = 'cam'; vp.appendChild(cam);
  cam.innerHTML = await (await fetch('static/live/method_live.svg')).text();
  const svg = cam.querySelector('svg'); svg.removeAttribute('width'); svg.removeAttribute('height');

  // ---------- steps ----------
  const PANEL = { all: [0, 0, FW, FH], a: [12, 158, 730, 343], ab: [110, 158, 668, 343], b: [442, 158, 336, 343], bc: [442, 158, 646, 343], c: [794, 158, 294, 343] };
  const A = '(a) Type and parent selection', B = '(b) Oracle and check against S', C = '(c) Constrained decoding';
  const STEPS = [
    { cam: 'all', flag: null, ms: 6000, k: 'Overview', t: 'Constrained decoding of one part. The model chooses which part to place and what it attaches to; we constrain <i>how</i> it attaches, so that it fits the build.' },
    { cam: 'a', flag: 'a1', ms: 8500, k: A, t: 'Given the caption and the build so far, <i>S</i>, the model writes the next part. Its type, an <b>arch</b>, is the model’s own choice.' },
    { cam: 'a', flag: 'a2', ms: 5000, k: A, t: 'Next it writes the parent: the part already in <i>S</i> that the arch will attach to.' },
    { cam: 'a', flag: 'a3', ms: 5500, k: A, t: 'Parents with no valid place for the arch are <b>vetoed</b> before the model chooses.' },
    { cam: 'a', flag: 'a4', ms: 5500, k: A, t: 'The model picks <b>g</b>, the base plate. How the arch attaches to it is still open.' },
    { cam: 'ab', flag: 'b1', ms: 6000, k: B, t: 'The part type and the parent’s type go to the <b>geometric oracle</b>, a table precomputed offline.' },
    { cam: 'b', flag: 'b2', ms: 5000, k: B, t: 'It lists every way the arch can attach to the plate. Four of them are shown.' },
    { cam: 'b', flag: 'b3', ms: 5500, k: B, t: 'Each candidate is placed in the build and checked for collisions. Two of these four collide.' },
    { cam: 'bc', flag: 'c1', ms: 6500, k: C, t: 'We tokenize the remaining valid candidates and build a prefix tree from them.' },
    // one step, three decoding stages (one per token): sub-flags s2, s3 switch on at their times within the step
    { cam: 'c', flag: 's1', sub: [['s2', 3900], ['s3', 7800]], ms: 12500, k: C, t: 'Tokens that do not lead to valid candidates according to the tree are penalized by <b>−β</b>, a tunable hyperparameter, and then a token is sampled.' },
    { cam: 'all', flag: 'end', ms: 6500, k: 'Next part', t: 'The arch joins the build, and the loop repeats for the next part.' },
  ];

  // ---------- camera: a CSS transform on .cam; one veil layer per framing, cross-faded ----------
  // framing of a step; (a) is centred, unclamped: its sides are blank (opaque veil)
  const target = name => { const [x, y, w, h] = PANEL[name]; if (name === 'all') return [0, T0, FW, VH]; const m = 10, hh = h + 2 * m, ww = hh * FW / VH, cx = x + w / 2; let x0 = cx - ww / 2; if (name !== 'a') x0 = Math.max(0, Math.min(FW - ww, x0)); return [x0, y - m, ww, hh]; };
  const VEIL = {};
  for (const [name, [x, y, w, h]] of Object.entries(PANEL)) {
    if (name === 'all') continue;
    const v = document.createElementNS(NS, 'svg'), r = 10; v.setAttribute('viewBox', `0 0 ${FW} ${FH}`); v.setAttribute('class', 'veil'); v.setAttribute('aria-hidden', 'true');
    v.innerHTML = `<path fill="#fff" fill-opacity="${name === 'a' ? 1 : .72}" fill-rule="evenodd" d="M-2000 -2000H4000V4000H-2000Z M${x + r} ${y}H${x + w - r}Q${x + w} ${y} ${x + w} ${y + r}V${y + h - r}Q${x + w} ${y + h} ${x + w - r} ${y + h}H${x + r}Q${x} ${y + h} ${x} ${y + h - r}V${y + r}Q${x} ${y} ${x + r} ${y}Z"/>`;
    cam.appendChild(v); VEIL[name] = v;
  }
  // the new part, bobbing: an overlay image at the figure position the builder recorded
  const [ax, ay, aw] = svg.querySelector('#arch-live').dataset.box.split(',').map(Number);
  const arch = document.createElement('img'); arch.className = 'arch-ov'; arch.src = 'static/live/arch_hl.webp'; arch.alt = '';
  Object.assign(arch.style, { left: ax / FW * 100 + '%', top: ay / FH * 100 + '%', width: aw / FW * 100 + '%' }); cam.appendChild(arch);
  let camName = 'all';
  function setCam(name, animate) {
    camName = name; const [x0, y0, w] = target(name), k = vp.clientWidth / FW, s = FW / w;
    cam.classList.toggle('anim', !!animate);
    cam.style.transform = `translate(${(-x0 * k * s).toFixed(2)}px,${(-y0 * k * s).toFixed(2)}px) scale(${s.toFixed(5)})`;
    for (const [n, v] of Object.entries(VEIL)) v.classList.toggle('on', n === name);
  }
  new ResizeObserver(() => setCam(camName, false)).observe(vp);

  // ---------- typed lines in the context box ----------
  const GREY = '#536276', PURPLE = '#6450a4', OLIVE = '#5F7A1E', TEAL = '#167568';
  const LINE1 = [['o ', GREY], ['arch 1x3', PURPLE], [' | yellow', GREY]];
  const LINE2a = [['g', OLIVE], [' stud stud', PURPLE]], LINE2b = [[' p hole b 0', TEAL]];
  const ty = [null, $('#ty1'), $('#ty2')], hl = [null, $('#hl1'), $('#hl2')], cur = $('#cur'), box = $('#ctx-box');
  let typer = 0;
  const placeCur = t => { const x = +t.getAttribute('x'), wdt = t.getComputedTextLength(); cur.setAttribute('x', x + wdt + 2); cur.setAttribute('y', +t.getAttribute('y') - 12.5); return wdt; };
  function setLine(k, segs, nChars) {   // render the first nChars of the segments as tspans
    const t = ty[k]; t.textContent = ''; let left = nChars ?? Infinity;
    for (const [str, col] of segs) { if (left <= 0) break; const sp = document.createElementNS(NS, 'tspan'); sp.setAttribute('fill', col); sp.textContent = str.slice(0, left); t.appendChild(sp); left -= str.length; }
    return placeCur(t);
  }
  const len = segs => segs.reduce((n, [s]) => n + s.length, 0);
  function typeLine(k, segs, from, animate, delay = 0) {   // segs: full line; type from character `from` to the end
    clearInterval(typer); const n = len(segs);
    const full = setLine(k, segs); hl[k].setAttribute('width', full + 10);
    if (!animate) return;
    let i = from; setLine(k, segs, i); later(delay, () => { typer = setInterval(() => { setLine(k, segs, ++i); if (i >= n) clearInterval(typer); }, 55); });
  }
  const setBox = hgt => { box.style.height = hgt + 'px'; };   // CSS transitions the height (no per-frame JS)

  // ---------- state ----------
  const FLAGS = STEPS.flatMap(s => [s.flag, ...(s.sub || []).map(x => x[0])]).filter(Boolean);
  let cur_ = -1, curCam = 'all', timers = [];
  const later = (ms, f) => timers.push(setTimeout(f, ms));
  const narr = $('#narr-text');
  function apply(i, animate) {
    timers.forEach(clearTimeout); timers = []; clearInterval(typer);
    const prev = cur_, S = STEPS[i]; cur_ = i;
    const on = new Set([...STEPS.slice(0, i).flatMap(s => [s.flag, ...(s.sub || []).map(x => x[0])]), STEPS[i].flag].filter(Boolean)), live = i > 0, wide = S.cam === 'a';
    const camChange = S.cam !== curCam, delay = animate && camChange && live ? 650 : 0;   // let the camera arrive before revealing
    setCam(S.cam, animate); curCam = S.cam;
    setBox(+box.dataset[live ? 'h1' : 'h0']);
    const fresh = animate && i === prev + 1;
    const reveal = () => {
      W.classList.toggle('live', live); W.classList.toggle('aw', wide); for (const f of FLAGS) W.classList.toggle('f-' + f, on.has(f));
      // the typed lines: line 1 at a1 (as arch 1x3 is chosen), line 2 ('g stud stud') at a4, its attachment (' p hole b 0') at the end
      const l2 = on.has('end') ? [...LINE2a, ...LINE2b] : LINE2a;
      if (!on.has('a1')) { setLine(1, [], 0); setLine(2, [], 0); }
      else if (!on.has('a4')) { setLine(2, [], 0); typeLine(1, LINE1, 0, fresh && S.flag === 'a1', 3400); }
      else { setLine(1, LINE1); typeLine(2, l2, S.flag === 'a4' ? 0 : len(LINE2a), fresh && (S.flag === 'a4' || on.has('end')), S.flag === 'a4' ? 400 : 900); }
      hl[1].classList.toggle('on', on.has('a1') && !on.has('a4')); hl[2].classList.toggle('on', on.has('a4'));
    };
    if (delay) later(delay, reveal); else reveal();
    for (const [f, ms] of S.sub || []) later(delay + ms, () => W.classList.add('f-' + f));   // the step's later stages
    narr.classList.add('fade'); later(animate ? 220 : 0, () => { narr.innerHTML = `<span class="kick">Step ${i + 1} of ${STEPS.length} · <i>${S.k}</i></span><p>${S.t}</p>`; narr.classList.remove('fade'); });
    $$('#dots button').forEach((b, j) => { b.classList.toggle('on', j === i); b.classList.toggle('done', j < i); b.style.setProperty('--p', playing ? 0 : 1); });
  }

  // ---------- controls / autoplay ----------
  const dots = $('#dots');
  STEPS.forEach((_, j) => { const b = document.createElement('button'); b.type = 'button'; b.setAttribute('aria-label', 'Step ' + (j + 1)); b.appendChild(document.createElement('i')); b.onclick = () => { setPlay(false); apply(j, true); }; dots.appendChild(b); });
  let playing = !matchMedia('(prefers-reduced-motion: reduce)').matches, visible = false, clock = 0, last = 0;
  const playBtn = $('#w-play');
  function setPlay(p) { playing = p; playBtn.textContent = p ? '❚❚' : '▶'; playBtn.setAttribute('aria-label', p ? 'Pause' : 'Play'); clock = 0; const d = $$('#dots button')[cur_]; if (d) d.style.setProperty('--p', p ? 0 : 1); }
  const go = d => { setPlay(false); apply((cur_ + d + STEPS.length) % STEPS.length, true); };
  playBtn.onclick = () => setPlay(!playing);
  $('#w-prev').onclick = () => go(-1);
  $('#w-next').onclick = () => go(1);
  // arrow keys step the walkthrough whenever it is on screen (not only when it has focus); space toggles play when it has focus
  document.addEventListener('keydown', e => {
    if (!visible || e.altKey || e.ctrlKey || e.metaKey || /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName || '')) return;
    if (e.key === 'ArrowRight') { e.preventDefault(); go(1); } else if (e.key === 'ArrowLeft') { e.preventDefault(); go(-1); }
    else if (e.key === ' ' && W.contains(document.activeElement)) { e.preventDefault(); playBtn.click(); }
  });
  new IntersectionObserver(es => { visible = es[0].isIntersecting; W.classList.toggle('off', !visible); }, { threshold: 0.15 }).observe(W);
  function tick(now) {
    const dt = Math.min(100, now - (last || now)); last = now;
    if (playing && visible && !document.hidden) {
      clock += dt; const d = $$('#dots button')[cur_]; if (d) d.style.setProperty('--p', Math.min(1, clock / STEPS[cur_].ms).toFixed(3));
      if (clock >= STEPS[cur_].ms) { clock = 0; apply((cur_ + 1) % STEPS.length, true); }
    }
    requestAnimationFrame(tick);
  }
  setPlay(playing); apply(0, false); requestAnimationFrame(tick);
  window.__walk = { apply, steps: STEPS.length, cur: () => cur_ };
})();
